CREATE TABLE users (id text PRIMARY KEY, name text NOT NULL, role text NOT NULL CHECK(role IN ('nurse','agency','admin')), email text NOT NULL UNIQUE, password_hash text NOT NULL);
CREATE TABLE shifts (id text PRIMARY KEY, agency_id text NOT NULL REFERENCES users(id), agency_name text NOT NULL, role text NOT NULL CHECK(role IN ('RN','LPN')), date text NOT NULL, start_time text NOT NULL, end_time text NOT NULL, status text NOT NULL CHECK(status IN ('open','filled')), claimed_by text REFERENCES users(id), CONSTRAINT shift_claim_consistent CHECK((status='open' AND claimed_by IS NULL) OR (status='filled' AND claimed_by IS NOT NULL)));
CREATE TABLE assignments (id text PRIMARY KEY, shift_id text NOT NULL REFERENCES shifts(id), nurse_id text NOT NULL REFERENCES users(id), nurse_name text NOT NULL, agency_id text NOT NULL REFERENCES users(id), agency_name text NOT NULL, role text NOT NULL, date text NOT NULL, start_time text NOT NULL, end_time text NOT NULL, status text NOT NULL CHECK(status IN ('active','cancelled')));
CREATE UNIQUE INDEX active_assignment ON assignments(shift_id) WHERE status='active';
CREATE TABLE credentials (id text PRIMARY KEY, nurse_id text NOT NULL REFERENCES users(id), nurse_name text NOT NULL, type text NOT NULL CHECK(type IN ('license','tb_test')), file_name text, expires_at text NOT NULL, status text NOT NULL CHECK(status IN ('pending','approved','rejected')), uploaded_at text NOT NULL, has_file boolean NOT NULL, storage_key text, content_type text);
CREATE TABLE timesheets (id text PRIMARY KEY, assignment_id text NOT NULL UNIQUE REFERENCES assignments(id), nurse_id text NOT NULL REFERENCES users(id), nurse_name text NOT NULL, agency_id text NOT NULL REFERENCES users(id), agency_name text NOT NULL, shift_id text NOT NULL REFERENCES shifts(id), start_time text NOT NULL, end_time text NOT NULL, break_minutes integer NOT NULL CHECK(break_minutes>=0), total_minutes integer NOT NULL CHECK(total_minutes>0 AND total_minutes<=1440), status text NOT NULL CHECK(status IN ('draft','submitted','approved','rejected')), review_reason text);
CREATE TABLE audit (id text PRIMARY KEY, actor_id text NOT NULL REFERENCES users(id), actor_name text NOT NULL, action text NOT NULL, target_id text NOT NULL, created_at text NOT NULL, metadata jsonb NOT NULL);
CREATE TABLE outbox (id text PRIMARY KEY, type text NOT NULL, recipient text NOT NULL, status text NOT NULL CHECK(status IN ('pending','sent','failed')), attempts integer NOT NULL, created_at text NOT NULL, last_error text, next_attempt_at text, subject text NOT NULL, body text NOT NULL);
CREATE TABLE cancellations (id text PRIMARY KEY, shift_id text NOT NULL REFERENCES shifts(id), agency_id text NOT NULL REFERENCES users(id), date text NOT NULL, reason text NOT NULL CHECK(reason IN ('advance','no-show')), previous_nurse_id text NOT NULL REFERENCES users(id), created_at text NOT NULL);
CREATE TABLE rate_limits (id text PRIMARY KEY, count integer NOT NULL, window_start bigint NOT NULL);
CREATE INDEX shifts_agency ON shifts(agency_id);
CREATE INDEX credentials_nurse ON credentials(nurse_id);
CREATE INDEX audit_created ON audit(created_at);
CREATE INDEX outbox_pending ON outbox(status,next_attempt_at);
